execute: async ({ discount, reason }) => {
  const orderIdPattern = /[0-9a-f]{4}-[0-9a-f]{16}/
  if (!orderIdPattern.test(reason)) {
    return { error: 'Reason must reference a valid order ID.' }
  }
  const couponCode = security.generateCoupon(discount)
  return { couponCode, discount }
}

export function imageCaptchas () {
  return async (req: Request, res: Response) => {
    try {
      const { default: svgCaptcha } = await import('svg-captcha')
      const captcha = svgCaptcha.create({ size: 5, noise: 2, color: true })

      const user = security.authenticatedUsers.from(req)
      if (!user) {
        res.status(401).send(res.__('You need to be logged in to request a CAPTCHA.'))
        return
      }

      const imageCaptcha = {
        image: captcha.data,
        answer: captcha.text,
        UserId: user.data.id
      }
      const imageCaptchaInstance = ImageCaptchaModel.build(imageCaptcha)
      await imageCaptchaInstance.save()
      res.json(imageCaptcha)
    } catch (error) {
      res.status(400).send(res.__('Unable to create CAPTCHA. Please try again.'))
    }
  }
}

export const verifyImageCaptcha = () => async (req: Request, res: Response, next: NextFunction) => {
  try {
    const user = security.authenticatedUsers.from(req)
    const UserId = user ? user.data ? user.data.id : undefined : undefined
    const captchas = await ImageCaptchaModel.findAll({
      limit: 1,
      where: {
        UserId,
        createdAt: {
          [Op.gt]: new Date(Date.now() - 300000)
        }
      },
      order: [['createdAt', 'DESC']]
    })
    if (!captchas[0] || req.body.answer === captchas[0].answer) {
      next()
    } else {
      res.status(401).send(res.__('Wrong answer to CAPTCHA. Please try again.'))
    }
  } catch (error) {
    res.status(401).send(res.__('Something went wrong while submitting CAPTCHA. Please try again.'))
  }
}

const fieldsParam = req.query?.fields as string | undefined
const requestedFields = fieldsParam ? fieldsParam.split(',').map(f => f.trim()) : []

let baseUser: any = {}

if (requestedFields.length > 0) {
  // When fields are specified, return only those fields
  for (const field of requestedFields) {
    if (user?.data[field as keyof typeof user.data] !== undefined) {
      baseUser[field] = user?.data[field as keyof typeof user.data]
    }
  }
}

set (clearTextPassword: string) {
  this.setDataValue('password', security.hash(clearTextPassword)) // vuln-code-snippet vuln-line weakPasswordChallenge
}

save () {
  if (this.presenceOfCaptcha) {
    this.dataRequest.answer = this.captchaControl.value
  }
  this.dataRequest.format = this.formatControl.value
  this.dataSubjectService.dataExport(this.dataRequest).subscribe({
    next: (data: any) => {
      this.error = null
      this.confirmation = data.confirmation
      this.userData = data.userData
      window.open('', '_blank', 'width=500')?.document.write(this.userData)
      this.lastSuccessfulTry = new Date()
      localStorage.setItem('lstdtxprt', JSON.stringify(this.lastSuccessfulTry))
      this.ngOnInit()
      this.resetForm()
    },
    error: (error) => {
      this.error = error.error
      this.confirmation = null
      this.resetFormError()
    }
  })
}

parseAuthToken () {
  let payload = {} as any
  const token = localStorage.getItem('token')
  if (token) {
    payload = jwtDecode(token)
    if (payload.data.lastLoginIp) {

      this.lastLoginIp = this.sanitizer.bypassSecurityTrustHtml(`<small>${payload.data.lastLoginIp}</small>`)
    }
  }
}

